#!/usr/bin/env python3
"""Readable release evidence alongside the downloadable game package."""
from pathlib import Path
import json,html,shutil,sys
root=Path(__file__).resolve().parents[1];out=Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=True)
audit=json.loads((root/'release/balance-audit.json').read_text())
rows=''.join(f"<tr><td>{html.escape(s['name'])}</td><td>{s['completed']} / {s['runs']}</td><td>{s['gameOvers']}</td><td>{s['strategyStops']}</td></tr>" for s in audit['experiments'][0]['summary'])
checks=''.join('<li>'+s+'</li>' for s in [
'Title, How to Play and Credits, including Author: astrofor.',
'Six short POKEY effects, with decay to silence; no music.',
'Chapel gallery: eight unique portraits, a painter-notes quest, shuffled locations, repeat-find protection and no extra resident image caches.',
'Complete native 12-victory campaign with purchases, upgrades, legal movement, enemy turns, casualties and the real final boss kill, followed by the automatic wedding ending.',
'Natural three-fight losing campaign, illustrated bankruptcy and safe restart.',
'Intro images/code reclaimed; exact full-quality story disk reads; missing/wrong/truncated media.',
'O shortcut removed; double-Fire skipping, locked encounter controls, hit effects and permanent casualties retained.',
'Both D600 and D700 VBXE register mappings; editor/simulator unit tests; Windows and WSL launcher file checks.',
'Self-contained package with XEX, companion ATR, launchers, instructions, credits and SHA-256 checksums.'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Prince and the Nymph — release checks</title><style>body{background:#10171b;color:#e9eee9;font:17px/1.6 system-ui;margin:auto;max-width:1050px;padding:30px}a{color:#eac17b}img{width:100%;image-rendering:pixelated;border:1px solid #52624e}section{margin:30px 0}.screens{display:grid;grid-template-columns:1fr 1fr;gap:18px}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #52624e}.note{border-left:4px solid #eac17b;padding:12px;background:#192329}@media(max-width:700px){.screens{grid-template-columns:1fr}}</style><h1>Prince and the Nymph</h1><p>Author: <strong>astrofor</strong>.</p><p><a href="prince-and-the-nymph.zip" download>Download complete game package</a> · <a href="README.txt">Instructions and credits</a> · <a href="SHA256SUMS">Checksums</a></p><section><h2>Release features</h2><p>Title menu, instructions, credits and short sound effects. No music or saves. The development O shortcut is removed. The regular game plays the wedding ending after the final boss; the standalone test viewer remains available for direct picture inspection.</p><div class="screens"><figure><img src="prince-and-the-nymph-title.png" alt="Actual native title menu"><figcaption>Native title menu</figcaption></figure><figure><img src="prince-and-the-nymph-credits.png" alt="Actual native astrofor credits"><figcaption>Native credits</figcaption></figure></div></section><section><h2>Validation</h2><ul>CHECKS</ul><p class="note">These checks execute assembled 6502 code with modeled VBXE and OS SIO behavior. Live Altirra playback and real VBXE/drive timing remain unverified because the desktop-control connection was unavailable. This is not a hardware certification.</p></section><section><h2>Balance review</h2><p>Five fixed shopping/tactics bots × all 256 native starting seeds. These are bot completion frequencies, not human win probabilities. A rigid purchasing strategy can fail even when another legal strategy is viable.</p><table><thead><tr><th>Bot</th><th>Completed</th><th>Game over</th><th>Other strategy stops</th></tr></thead><tbody>ROWS</tbody></table><p>DECISION</p><p>The poor mounted and mixed bot results remain a balance concern for human playtesting. The release does not claim every army composition is equally effective.</p><p><a href="prince-and-the-nymph-balance-audit.json">Full balance review</a> · <a href="prince-and-the-nymph-native-campaign-results.json">Native winning and losing campaign logs</a></p></section>'''
page=page.replace('CHECKS',checks).replace('ROWS',rows).replace('DECISION',html.escape(audit['decision']))
(out/'prince-and-the-nymph-release.html').write_text(page)
for source,name in [('balance-audit.json','prince-and-the-nymph-balance-audit.json'),('native-campaign-results.json','prince-and-the-nymph-native-campaign-results.json')]:shutil.copyfile(root/'release'/source,out/name)
print('Published release report and auditable campaign/balance results.')
